const lockArcLore = `-- name: LockArcLore :exec

SELECT pg_advisory_xact_lock(hashtextextended('lore:' || $1::uuid::text, 0))
`

// Lore domain queries: claims on characters, connected-group membership and
// the reads behind ListClaims and GetLore. Enumerated columns hold the full
// proto value name; callers pass them as text parameters.
// Serialises every lore writer on one arc for the rest of the transaction.
// An advisory lock, not a row lock on arcs, so writers outside the lore
// domain that lock a perspective and then update the arc row never wait on
// it.
func (q *Queries) LockArcLore(ctx context.Context, arcID uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockArcLore, arcID)
	return err
}

const lockClaimStatus = `-- name: LockClaimStatus :one
SELECT status FROM claims WHERE id = $1 FOR UPDATE
`

func (q *Queries) LockClaimStatus(ctx context.Context, id uuid.UUID) (string, error) {
	row := q.db.QueryRow(ctx, lockClaimStatus, id)
	var status string
	err := row.Scan(&status)
	return status, err
}

const lockLorePost = `-- name: LockLorePost :one
SELECT lp.id, lp.lore_id, lp.author_id, lp.reply_to_id, lp.deleted_at, lp.hidden_at,
       u.deleted_at AS author_deleted_at,
       (top.hidden_at IS NOT NULL)::boolean AS branch_hidden
FROM lore_posts lp
JOIN users u ON u.id = lp.author_id
LEFT JOIN lore_posts top ON top.id = lp.reply_to_id
WHERE lp.id = $1
FOR UPDATE OF lp
`

type LockLorePostRow struct {
	ID              uuid.UUID
	LoreID          uuid.UUID
	AuthorID        uuid.UUID
	ReplyToID       uuid.NullUUID
	DeletedAt       pgtype.Timestamptz
	HiddenAt        pgtype.Timestamptz
	AuthorDeletedAt pgtype.Timestamptz
	BranchHidden    bool
}

// One post with what the thread's write rules read, its row locked. A
// reply's top-level post decides whether a moderator hid the whole branch.
func (q *Queries) LockLorePost(ctx context.Context, id uuid.UUID) (LockLorePostRow, error) {
	row := q.db.QueryRow(ctx, lockLorePost, id)
	var i LockLorePostRow
	err := row.Scan(
		&i.ID,
		&i.LoreID,
		&i.AuthorID,
		&i.ReplyToID,
		&i.DeletedAt,
		&i.HiddenAt,
		&i.AuthorDeletedAt,
		&i.BranchHidden,
	)
	return i, err
}

